    array (
      'about__block_t11' => 'Nākotnes portreta foto',
      'about__block_t12' => '<span class="orange">Pirmais un vissvarīgākais solis</span> ir izvēlēties labas fotogrāfijas nākotnes portretam un definēt vispārējo ideju. Ja jums jau ir laba fotogrāfija, kuru vēlaties, lai mākslinieks pārzīmētu, šī ir vienkāršākā iespēja. Mākslinieks nekavējoties sāks strādāt pie šedevra.',
      'about__block_t13' => 'Ja jums ir tikai sejas fotoattēls un vēlaties mainīt fonu un apkārtni, jums būs <span class="orange">jāapspriež detaļas un iespējas ar mākslinieku.</span> Viņš datorā iesniegs vairākus kompozīcijas priekšlikumus, kurus jūs varēsiet redzēt un apstiprināt.',
      'about__block_t14' => '<span class="orange">Kvalitāte<br> foto</span><br> lai iegūtu labāko rezultātu',
      'about__block_t21' => 'Mākslinieks zīmē skici',
      'about__block_t22' => '<span class="orange">Otrais solis</span> ir tad, kad attēls ir apstiprināts, mākslinieks sāk darbu. Mākslinieks, pēc jūsu vēlmēm, uz audekla veido zīmuļa skici!',
      'about__block_t23' => 'Mūsu darbnīcā ViarCanvas mēs izmantojam tikai augstas kvalitātes <span class="orange">dabīgo audeklu</span> !',
      'about__block_t24' => 'Materiālu spilgtums un izturība vairāk nekā <span class="orange">100 gadus!</span> Audekls saglabās savu spriegumu un nenokarāsies!',
      'about__block_t25' => 'Mēs fotografējam <span class="orange">visus posmus</span> un nosūtām tos jums pa e-pastu.',
      'about__block_t31' => 'Apakškrāsošana',
      'about__block_t32' => '<span class="orange">Trešais solis</span> ir apakšgleznošana, kurā mākslinieks uz audekla uzklāj plānu krāsas kārtu, lai piešķirtu tam sākotnējo formu un apjomu.<br><br> Tas arī izceļ tumšākas un gaišākas zonas. Kad pirmais krāsas slānis ir nožuvis, detalizēts darbs sākas vairākos turpmākajos posmos.',
      'about__block_t33' => 'Šī tehnika ļauj padarīt zīmējumu apjomīgāku, dzīvīgāku un gleznaināku, piešķirot tam lielāku dziļumu un reālismu.',
      'about__block_t34' => 'Krāsas <span class="orange">uz<br> 100% drošs un videi draudzīgs!</span>',
      'about__block_t41' => 'Pēdējais posms<br> + Portreta aizsardzība',
      'about__block_t42' => '<span class="orange">Ceturtais solis</span> : mūsu mākslinieks uzzīmēs visas portreta detaļas.<br> Kad portrets ir pilnībā pabeigts, mēs to nofotografējam un nosūtām jums augstas kvalitātes attēlus galīgajai apstiprināšanai.',
      'about__block_t43' => '<span class="orange">Noteikti pārklājiet gleznu ar laku,</span> lai pasargātu to no mehāniskas iedarbības.',
      'about__block_t44' => '<span class="orange">Gleznas pārklāšana ar aizsargājošu</span> akrila laku',
      'about__block_t51' => 'Dizains bagešu rāmī',
      'about__block_t52' => '<span class="orange">Piektais solis</span> – kad glezna ir uzstiepta uz rāmja, tā jau kļūst par gatavu un vērtīgu dāvanu.<br> Tomēr, lai portrets izskatītos pilnīgs, iesakām to ierāmēt.',
      'about__block_t53' => '<span class="orange">Mēs jums piedāvāsim vairākas piemērotas bagešu rāmju iespējas</span> - dažādus veidus un cenu kategorijas, no kurām jūs varēsiet izvēlēties sev piemērotāko.<br> Tādā veidā jūsu portrets iegūs pabeigtu un elegantu izskatu un kļūs par vēl pievilcīgāku un stilīgāku dāvanu.',
      'about__block_t54' => '<span class="orange">Liels<br> izvēle</span><br> bagešu rāmji',
      'about__block_t61' => 'Iepakošana un piegāde',
      'about__block_t62' => '<span class="orange">Sestais solis</span> . Mēs īpaši rūpējamies, lai transportēšanas laikā darbs saglabātu savu nevainojamu stāvokli.<br><br> Mēs pieliekam ievērojamas pūles, lai nodrošinātu darba drošu aizsardzību transportēšanas laikā.<br><br> Mūsu mērķis ir nodrošināt, lai jūsu mākslas darbs sniegtu jums tikai pozitīvas emocijas, neskatoties uz jebkādu kustību un pasniegšanas veidu.',
      'about__block_t63' => 'Piegāde uz jebkuru <span class="orange">valsti un pilsētu Eiropā</span>',
    ),
